function PTSD_Register()
	local k = 1
	while PTSD_NPCS[k] do
		ReLoadScript(PTSD_NPCS[k][7])
		k = k + 1
	end
	k = 1
	while PTSD_REBIND[k] do
		ReLoadScript(PTSD_REBIND[k][3])
		k = k + 1
	end
	k = 1
	while PTSD_DEATH[k] do
		ReLoadScript(PTSD_DEATH[k])
		k = k + 1
	end
	ReLoadScript(PTSD_DROP_SCRIPT)
end

function PTSD_EnsureNpcs()
	local k = 1
	while PTSD_NPCS[k] do
		local s = PTSD_NPCS[k]
		local ni = PTSD_SPAWNED[k]
		local ok = nil
		if ni and ni > 0 and GetNpcName(ni) == s[6] and GetNpcPos(ni) == s[2] then ok = 1 end
		if not ok then
			local sw = SubWorldID2Idx(s[2])
			if sw and sw >= 0 then
				ni = AddNpc(s[3], 1, sw, s[4], s[5], 0)
				if ni and ni > 0 then
					SetNpcName(ni, s[6])
					SetNpcScript(ni, s[7])
					PTSD_SPAWNED[k] = ni
				end
			end
		end
		k = k + 1
	end
end

function PTSD_Rebind()
	local k = 1
	local need = nil
	while PTSD_REBIND[k] do
		local r = PTSD_REBIND[k]
		local ni = PTSD_REBOUND[k]
		if ni and ni > 0 and GetNpcName(ni) == r[2] and GetNpcPos(ni) == r[1] then
			SetNpcScript(ni, r[3])
		else
			PTSD_REBOUND[k] = nil
			need = 1
		end
		k = k + 1
	end
	if not need then return end
	local i = 1
	while i < PTSD_MAX_NPC do
		local nm = GetNpcName(i)
		if nm and nm ~= "" then
			k = 1
			while PTSD_REBIND[k] do
				local r = PTSD_REBIND[k]
				if not PTSD_REBOUND[k] and nm == r[2] and GetNpcPos(i) == r[1] then
					SetNpcScript(i, r[3])
					PTSD_REBOUND[k] = i
				end
				k = k + 1
			end
		end
		i = i + 1
	end
end

-- quest-drop ActionScript on the field monsters of the Dong Di maps; only templates without a project
-- ActionScript (not in PT_SPAWN_DROP_TIDS of spawn_main.lua) are listed in PTSD_DROPMAPS
function PTSD_BindDrops()
	local n = 0
	local i = 1
	while i < PTSD_MAX_NPC do
		local w = GetNpcPos(i)
		local t = w and PTSD_DROPMAPS[w]
		if t then
			local tpl = GetNpcTemplateID(i)
			if tpl and t[tpl] then
				SetNpcScript(i, PTSD_DROP_SCRIPT)
				n = n + 1
			end
		end
		i = i + 1
	end
	PTSD_DROP_BOUND = n
	return n
end

function PTEXT_sudo_dongdi_Tick()
	if not PTSD_INIT then
		PTSD_Register()
		PTSD_INIT = 1
	end
	PTSD_EnsureNpcs()
	PTSD_Rebind()
	-- the field population (spawn_main.lua) is spawned over several ticks: bind once it is complete (or after
	-- 15 minutes at the latest), then again every 10 minutes for monsters spawned later
	if PT_SPAWN_DONE or PTSD_TICKS >= 15 then
		if (not PTSD_DROP_AT) or PTSD_TICKS - PTSD_DROP_AT >= 10 then
			PTSD_BindDrops()
			PTSD_DROP_AT = PTSD_TICKS
		end
	end
	PTSD_TICKS = PTSD_TICKS + 1
end
